/**
 * Génération d'identifiants : courts, uniques, stables, triables
 * grossièrement dans le temps (base36 de l'horloge + entropie).
 */

let counter = 0;

const rand = (): string => {
  // crypto si dispo (navigateur / Node ≥ 19), sinon Math.random.
  const g = globalThis as { crypto?: Crypto };
  if (g.crypto?.getRandomValues) {
    const buf = new Uint32Array(2);
    g.crypto.getRandomValues(buf);
    return (
      (buf[0] ?? 0).toString(36).padStart(7, "0") +
      (buf[1] ?? 0).toString(36).padStart(7, "0")
    ).slice(0, 10);
  }
  return Math.random().toString(36).slice(2, 12).padEnd(10, "0");
};

/** Crée un id préfixé, ex. createId("el") → "el_lx2k9…". */
export function createId(prefix: string): string {
  counter = (counter + 1) % 1296; // 36^2
  const time = Date.now().toString(36);
  const seq = counter.toString(36).padStart(2, "0");
  return `${prefix}_${time}${seq}${rand()}`;
}

export const createElementId = (): string => createId("el");
export const createTemplateId = (): string => createId("tpl");
export const createDocumentId = (): string => createId("doc");
export const createComponentId = (): string => createId("cmp");
