/**
 * Micro-couche DOM des composants Typos. Pas un framework : trois
 * fonctions pour écrire du DOM vanilla lisible, et rien d'autre.
 */

type Child = Node | string | null | undefined | false;

export interface HProps {
  class?: string;
  text?: string;
  html?: string;
  title?: string;
  attrs?: Record<string, string>;
  style?: Partial<CSSStyleDeclaration>;
  on?: Partial<{
    [K in keyof HTMLElementEventMap]: (ev: HTMLElementEventMap[K]) => void;
  }>;
}

/** h("div", { class: "x", on: { click } }, child1, child2…) */
export function h<K extends keyof HTMLElementTagNameMap>(
  tag: K,
  props: HProps = {},
  ...children: Child[]
): HTMLElementTagNameMap[K] {
  const el = document.createElement(tag);
  if (props.class) el.className = props.class;
  if (props.text !== undefined) el.textContent = props.text;
  if (props.html !== undefined) el.innerHTML = props.html;
  if (props.title) el.title = props.title;
  if (props.attrs) {
    for (const [k, v] of Object.entries(props.attrs)) el.setAttribute(k, v);
  }
  if (props.style) Object.assign(el.style, props.style);
  if (props.on) {
    for (const [name, fn] of Object.entries(props.on)) {
      el.addEventListener(name, fn as EventListener);
    }
  }
  for (const child of children) {
    if (child === null || child === undefined || child === false) continue;
    el.append(typeof child === "string" ? document.createTextNode(child) : child);
  }
  return el;
}

/** Vide un conteneur puis y monte des enfants. */
export function replaceChildren(container: HTMLElement, ...children: Child[]): void {
  container.textContent = "";
  for (const child of children) {
    if (child === null || child === undefined || child === false) continue;
    container.append(typeof child === "string" ? document.createTextNode(child) : child);
  }
}

/** Collecteur de désabonnements : disposer.add(engine.on(...)); disposer.flush(). */
export function makeDisposer(): { add: (fn: () => void) => void; flush: () => void } {
  const fns: Array<() => void> = [];
  return {
    add: (fn) => fns.push(fn),
    flush: () => {
      for (const fn of fns.splice(0)) fn();
    },
  };
}

/** Anti-rebond minimal (rendus groupés). */
export function debounce<A extends unknown[]>(
  fn: (...args: A) => void,
  ms: number,
): (...args: A) => void {
  let t: ReturnType<typeof setTimeout> | null = null;
  return (...args: A) => {
    if (t) clearTimeout(t);
    t = setTimeout(() => fn(...args), ms);
  };
}
