/* ------------------------------------------------------------------ */
/* Construction d'un sous-arbre à partir d'une définition              */
/* ------------------------------------------------------------------ */

/**
 * Transforme une ElementDefinition (JSON récursif) en TyposElement,
 * en générant des ids frais partout et en marquant `origin: "template"`.
 */
export function elementFromDefinition(
  def: ElementDefinition,
  directivePrefix?: string,
  now?: () => string,
): TyposElement {
  return createElement(def.type, {
    name: def.name,
    origin: "template",
    isComponentRoot: def.isComponentRoot,
    componentRef: def.componentRef ?? null,
    attrs: def.attrs,
    styleOptions: def.styleOptions,
    customCss: def.customCss,
    classes: def.classes,
    innerHtml: def.innerHtml,
    script: def.script,
    children: (def.children ?? []).map((c) =>
      elementFromDefinition(c, directivePrefix, now),
    ),
    directivePrefix,
    now,
  });
}

/** Table indexée pour lookup rapide. */
export const TEMPLATES_BY_KEY: ReadonlyMap<string, TemplateDefinition> = new Map(
  DEFAULT_TEMPLATES.map((t) => [t.key, t]),
);
