import type {
  ElementPatch,
  EmitProfile,
  EngineEventMap,
  EngineListener,
  EngineWildcardListener,
  HtmlGenOptions,
  TemplateTarget,
  TyposDocument,
  TyposElement,
  TyposTemplate,
} from "../core/types.js";
import { Emitter } from "./events.js";
import {
  createDocument,
  documentHash,
  parseDocument,
  parseDocumentValue,
  serializeDocument,
  type CreateDocumentOptions,
  type SerializeOptions,
} from "../core/serialize.js";
import { recomputeDerivedDirectives } from "../core/directives.js";
import { createElement, type CreateElementOptions } from "../core/element.js";
import {
  cloneSubtree,
  findById,
  insertAt,
  moveTo,
  removeById,
  reorder,
  unwrapElement,
  updateElement,
  wrapElement,
} from "../core/tree.js";
import { treeToHtml } from "../core/html-gen.js";
import { parseHtmlToTree } from "../core/html-parse.js";
import { createTemplateId } from "../core/ids.js";
import {
  elementFromDefinition,
  type ElementDefinition,
} from "../config/defaults.js";

/**
 * TyposEngine — le moteur d'édition, sans le moindre pixel.
 *
 * Invariants (les mêmes que KantoEngine) :
 * - l'état est IMMUABLE : chaque mutation produit un nouveau document,
 *   les branches intactes sont partagées — l'historique est une pile de
 *   références, pas de copies ;
 * - UN SEUL flux d'événements : l'UI s'abonne, jamais l'inverse ;
 * - les directives dérivées sont recalculées par le moteur après chaque
 *   mutation — rien d'autre n'a le droit d'y toucher ;
 * - toute mutation passe par commit() : historique, recalcul, événements
 *   et dirty y sont gérés une seule fois, au même endroit.
 */

interface HistoryEntry {
  label: string;
  snapshot: TyposDocument;
  at: number;
  coalesceKey?: string;
}

interface CommitEmit<K extends keyof EngineEventMap = keyof EngineEventMap> {
  name: K;
  payload: EngineEventMap[K];
}

interface CommitOptions {
  /** Mutations consécutives de même clé fusionnées dans l'historique. */
  coalesceKey?: string;
}

export interface EngineOptions {
  document?: TyposDocument;
  /** Profondeur maximale d'historique (défaut : 200). */
  historyLimit?: number;
  /** Fenêtre de coalescence en ms (défaut : 1000). */
  coalesceWindowMs?: number;
  now?: () => string;
}

export interface AddElementOptions extends CreateElementOptions {
  parentId?: string;
  index?: number;
  templateId?: string;
}

export class TyposEngine {
  private emitter = new Emitter();
  private doc: TyposDocument;
  private selectionIds: string[] = [];
  private undoStack: HistoryEntry[] = [];
  private redoStack: HistoryEntry[] = [];
  private savedHash: string;
  private dirtyFlag = false;
  private batchDepth = 0;
  private batchBefore: TyposDocument | null = null;
  private batchEmits: CommitEmit[] = [];
  private batchLabel = "";
  private readonly historyLimit: number;
  private readonly coalesceWindowMs: number;
  private readonly now: () => string;

  constructor(options: EngineOptions = {}) {
    this.doc = options.document ?? createDocument();
    this.historyLimit = options.historyLimit ?? 200;
    this.coalesceWindowMs = options.coalesceWindowMs ?? 1000;
    this.now = options.now ?? (() => new Date().toISOString());
    this.savedHash = documentHash(this.doc);
  }

  /* ---------------------------------------------------------------- */
  /* Lecture                                                           */
  /* ---------------------------------------------------------------- */

  get document(): TyposDocument {
    return this.doc;
  }

  get activeTemplate(): TyposTemplate {
    const t = this.doc.templates.find((t2) => t2.id === this.doc.activeTemplateId);
    if (!t) throw new Error("Typos: activeTemplateId incohérent.");
    return t;
  }

  /** Arbre du template actif. */
  get tree(): TyposElement {
    return this.activeTemplate.tree;
  }

  get selection(): readonly string[] {
    return this.selectionIds;
  }

  get canUndo(): boolean {
    return this.undoStack.length > 0;
  }

  get canRedo(): boolean {
    return this.redoStack.length > 0;
  }

  get isDirty(): boolean {
    return this.dirtyFlag;
  }

  findElement(id: string, templateId?: string): TyposElement | null {
    const t = this.template(templateId);
    return t ? findById(t.tree, id) : null;
  }

  /** HTML du template actif (ou donné), profil du document par défaut. */
  getHtml(options: HtmlGenOptions = {}, templateId?: string): string {
    const t = this.template(templateId);
    if (!t) return "";
    return treeToHtml(t.tree, {
      profile: this.doc.settings.emitProfile,
      directivePrefix: this.doc.settings.directivePrefix,
      ...options,
    });
  }

  /* ---------------------------------------------------------------- */
  /* Événements                                                        */
  /* ---------------------------------------------------------------- */

  on<K extends keyof EngineEventMap>(name: K, fn: EngineListener<K>): () => void;
  on(name: "*", fn: EngineWildcardListener): () => void;
  on(name: string, fn: never): () => void {
    return this.emitter.on(name as "*", fn);
  }

  off(name: string, fn: (payload: never, name: never) => void): void {
    this.emitter.off(name, fn);
  }

  /* ---------------------------------------------------------------- */
  /* Cycle de vie du document                                          */
  /* ---------------------------------------------------------------- */

  newDocument(options: CreateDocumentOptions = {}): TyposDocument {
    this.doc = createDocument({ now: this.now, ...options });
    this.resetTransient();
    this.emitter.emit("document:new", { document: this.doc });
    return this.doc;
  }

  /** Charge un document : objet v2, JSON v2, ou n'importe quel format v1. */
  loadDocument(input: string | object): TyposDocument {
    const { document } =
      typeof input === "string" ? parseDocument(input) : parseDocumentValue(input);
    this.doc = document;
    this.resetTransient();
    this.emitter.emit("document:loaded", { document: this.doc });
    return this.doc;
  }

  toJSON(options?: SerializeOptions): string {
    return serializeDocument(this.doc, options);
  }

  markSaved(): void {
    this.savedHash = documentHash(this.doc);
    this.setDirty(false);
  }

  rename(name: string): boolean {
    return this.commit(`Renommer en « ${name} »`, (doc) =>
      doc.name === name
        ? null
        : { doc: { ...doc, name }, emits: [{ name: "document:renamed", payload: { name } }] },
    );
  }

  /** Profil d'émission HTML par défaut du document. */
  setEmitProfile(profile: EmitProfile): boolean {
    return this.commit("Changer le profil d'émission", (doc) =>
      doc.settings.emitProfile === profile
        ? null
        : {
            doc: { ...doc, settings: { ...doc.settings, emitProfile: profile } },
            emits: [],
          },
    );
  }

  /* ---------------------------------------------------------------- */
  /* Templates                                                         */
  /* ---------------------------------------------------------------- */

  addTemplate(
    options: { name?: string; target?: TemplateTarget; cloneFromId?: string } = {},
  ): string {
    const id = createTemplateId();
    this.commit("Ajouter un template", (doc) => {
      const source = options.cloneFromId
        ? doc.templates.find((t) => t.id === options.cloneFromId)
        : undefined;
      const tree = source
        ? source.tree
        : createElement("div", {
            name: "root",
            origin: "template",
            directivePrefix: doc.settings.directivePrefix,
            now: this.now,
          });
      const template: TyposTemplate = {
        id,
        name: options.name ?? `Template ${doc.templates.length + 1}`,
        target: options.target ?? source?.target ?? "web",
        tree,
      };
      return {
        doc: { ...doc, templates: [...doc.templates, template] },
        emits: [{ name: "template:added", payload: { templateId: id } }],
        recompute: [id],
      };
    });
    return id;
  }

  /** Refuse de supprimer le dernier template. */
  removeTemplate(templateId: string): boolean {
    return this.commit("Supprimer un template", (doc) => {
      if (doc.templates.length <= 1) return null;
      if (!doc.templates.some((t) => t.id === templateId)) return null;
      const templates = doc.templates.filter((t) => t.id !== templateId);
      const activeTemplateId =
        doc.activeTemplateId === templateId
          ? (templates[0] as TyposTemplate).id
          : doc.activeTemplateId;
      return {
        doc: { ...doc, templates, activeTemplateId },
        emits: [
          { name: "template:removed", payload: { templateId } },
          ...(activeTemplateId !== doc.activeTemplateId
            ? [{ name: "template:activated", payload: { templateId: activeTemplateId } } as CommitEmit]
            : []),
        ],
      };
    });
  }

  renameTemplate(templateId: string, name: string): boolean {
    return this.commit(`Renommer le template`, (doc) => {
      const t = doc.templates.find((t2) => t2.id === templateId);
      if (!t || t.name === name) return null;
      return {
        doc: this.withTemplate(doc, templateId, { name }),
        emits: [{ name: "template:renamed", payload: { templateId, name } }],
      };
    });
  }

  setTemplateTarget(templateId: string, target: TemplateTarget): boolean {
    return this.commit("Changer la cible du template", (doc) => {
      const t = doc.templates.find((t2) => t2.id === templateId);
      if (!t || t.target === target) return null;
      return {
        doc: this.withTemplate(doc, templateId, { target }),
        emits: [{ name: "template:target", payload: { templateId, target } }],
        recompute: [templateId], // la cible fait partie des dérivées
      };
    });
  }

  /** Marque la version principale (mode composant) — exclusif. */
  setMainVersion(templateId: string): boolean {
    return this.commit("Définir la version principale", (doc) => {
      if (!doc.templates.some((t) => t.id === templateId)) return null;
      return {
        doc: {
          ...doc,
          templates: doc.templates.map((t) => ({ ...t, isMain: t.id === templateId })),
        },
        emits: [],
      };
    });
  }

  /** L'activation ne mute pas le contenu : hors historique. */
  setActiveTemplate(templateId: string): boolean {
    if (
      this.doc.activeTemplateId === templateId ||
      !this.doc.templates.some((t) => t.id === templateId)
    ) {
      return false;
    }
    this.doc = { ...this.doc, activeTemplateId: templateId };
    this.emitter.emit("template:activated", { templateId });
    return true;
  }

  /* ---------------------------------------------------------------- */
  /* Éléments                                                          */
  /* ---------------------------------------------------------------- */

  /**
   * Insère un sous-arbre décrit en JSON (squelette prêt à l'emploi).
   * Retourne l'id de la racine insérée, ou null.
   */
  insertTemplate(
    definition: ElementDefinition,
    options: { parentId?: string; index?: number; templateId?: string } = {},
  ): string | null {
    const element = elementFromDefinition(
      definition,
      this.doc.settings.directivePrefix,
      this.now,
    );
    return this.addElement(element, options);
  }

  /**
   * Ajoute un élément (type + options, ou élément déjà construit).
   * Parent par défaut : racine du template actif. Retourne l'id, ou null.
   */
  addElement(
    typeOrElement: string | TyposElement,
    options: AddElementOptions = {},
  ): string | null {
    const element =
      typeof typeOrElement === "string"
        ? createElement(typeOrElement, {
            origin: "palette",
            directivePrefix: this.doc.settings.directivePrefix,
            now: this.now,
            ...options,
          })
        : typeOrElement;

    const ok = this.commit(`Ajouter <${element.type}>`, (doc) => {
      const t = this.template(options.templateId, doc);
      if (!t) return null;
      const parentId = options.parentId ?? t.tree.id;
      const { root } = insertAt(t.tree, parentId, element, options.index);
      if (root === t.tree) return null;
      return {
        doc: this.withTemplate(doc, t.id, { tree: root }),
        emits: [
          {
            name: "element:added",
            payload: { templateId: t.id, elementId: element.id, parentId },
          },
        ],
        recompute: [t.id],
      };
    });
    return ok ? element.id : null;
  }

  removeElement(id: string, templateId?: string): boolean {
    return this.commit("Supprimer l'élément", (doc) => {
      const t = this.template(templateId, doc);
      if (!t) return null;
      const root = removeById(t.tree, id);
      if (root === t.tree) return null;
      return {
        doc: this.withTemplate(doc, t.id, { tree: root }),
        emits: [{ name: "element:removed", payload: { templateId: t.id, elementId: id } }],
        recompute: [t.id],
      };
    });
  }

  moveElement(
    id: string,
    newParentId: string,
    index?: number,
    templateId?: string,
  ): boolean {
    return this.commit("Déplacer l'élément", (doc) => {
      const t = this.template(templateId, doc);
      if (!t) return null;
      const root = moveTo(t.tree, id, newParentId, index);
      if (root === t.tree) return null;
      return {
        doc: this.withTemplate(doc, t.id, { tree: root }),
        emits: [
          {
            name: "element:moved",
            payload: {
              templateId: t.id,
              elementId: id,
              parentId: newParentId,
              index: index ?? -1,
            },
          },
        ],
        recompute: [t.id],
      };
    });
  }

  reorderElement(id: string, newIndex: number, templateId?: string): boolean {
    return this.commit("Réordonner l'élément", (doc) => {
      const t = this.template(templateId, doc);
      if (!t) return null;
      const root = reorder(t.tree, id, newIndex);
      if (root === t.tree) return null;
      return {
        doc: this.withTemplate(doc, t.id, { tree: root }),
        emits: [
          {
            name: "element:moved",
            payload: { templateId: t.id, elementId: id, parentId: "", index: newIndex },
          },
        ],
        recompute: [t.id],
      };
    });
  }

  /**
   * Patch partiel. `coalesceKey` fusionne les frappes successives dans
   * une seule entrée d'historique (ex. "style:el_x:width").
   */
  updateElement(
    id: string,
    patch: ElementPatch,
    options: { templateId?: string; coalesceKey?: string } = {},
  ): boolean {
    return this.commit(
      "Modifier l'élément",
      (doc) => {
        const t = this.template(options.templateId, doc);
        if (!t) return null;
        const root = updateElement(
          t.tree,
          id,
          patch,
          doc.settings.directivePrefix,
          this.now,
        );
        if (root === t.tree) return null;
        return {
          doc: this.withTemplate(doc, t.id, { tree: root }),
          emits: [
            { name: "element:updated", payload: { templateId: t.id, elementId: id } },
          ],
          recompute: [t.id],
        };
      },
      { coalesceKey: options.coalesceKey },
    );
  }

  cloneElement(id: string, templateId?: string): string | null {
    let cloneId: string | null = null;
    this.commit("Cloner l'élément", (doc) => {
      const t = this.template(templateId, doc);
      if (!t) return null;
      const { root, clone } = cloneSubtree(
        t.tree,
        id,
        doc.settings.directivePrefix,
        this.now,
      );
      if (root === t.tree) return null;
      cloneId = clone.id;
      return {
        doc: this.withTemplate(doc, t.id, { tree: root }),
        emits: [
          {
            name: "element:cloned",
            payload: { templateId: t.id, sourceId: id, cloneId: clone.id },
          },
        ],
        recompute: [t.id],
      };
    });
    return cloneId;
  }

  wrapElement(id: string, wrapperType = "div", templateId?: string): string | null {
    const wrapper = createElement(wrapperType, {
      origin: "api",
      directivePrefix: this.doc.settings.directivePrefix,
      now: this.now,
    });
    const ok = this.commit(`Envelopper dans <${wrapperType}>`, (doc) => {
      const t = this.template(templateId, doc);
      if (!t) return null;
      const root = wrapElement(t.tree, id, wrapper);
      if (root === t.tree) return null;
      return {
        doc: this.withTemplate(doc, t.id, { tree: root }),
        emits: [
          {
            name: "element:added",
            payload: { templateId: t.id, elementId: wrapper.id, parentId: "" },
          },
        ],
        recompute: [t.id],
      };
    });
    return ok ? wrapper.id : null;
  }

  unwrapElement(id: string, templateId?: string): boolean {
    return this.commit("Dissoudre l'élément", (doc) => {
      const t = this.template(templateId, doc);
      if (!t) return null;
      const root = unwrapElement(t.tree, id);
      if (root === t.tree) return null;
      return {
        doc: this.withTemplate(doc, t.id, { tree: root }),
        emits: [{ name: "element:removed", payload: { templateId: t.id, elementId: id } }],
        recompute: [t.id],
      };
    });
  }

  /** Remplace l'arbre du template (actif par défaut) par du HTML importé. */
  importHtml(html: string, css?: string, templateId?: string): boolean {
    return this.commit("Importer du HTML", (doc) => {
      const t = this.template(templateId, doc);
      if (!t) return null;
      const tree = parseHtmlToTree({
        html,
        css,
        directivePrefix: doc.settings.directivePrefix,
      });
      return {
        doc: this.withTemplate(doc, t.id, { tree }),
        emits: [
          { name: "element:updated", payload: { templateId: t.id, elementId: tree.id } },
        ],
        recompute: [t.id],
      };
    });
  }

  /* ---------------------------------------------------------------- */
  /* Sélection (hors historique)                                       */
  /* ---------------------------------------------------------------- */

  select(ids: string[]): void {
    const valid = ids.filter((id) =>
      this.doc.templates.some((t) => findById(t.tree, id)),
    );
    if (
      valid.length === this.selectionIds.length &&
      valid.every((id, i) => id === this.selectionIds[i])
    ) {
      return;
    }
    this.selectionIds = valid;
    this.emitter.emit("selection:changed", { ids: [...valid] });
  }

  clearSelection(): void {
    this.select([]);
  }

  /* ---------------------------------------------------------------- */
  /* Transactions                                                      */
  /* ---------------------------------------------------------------- */

  /**
   * Regroupe plusieurs mutations en UNE entrée d'historique et un seul
   * document:changed final. Imbriquable.
   */
  batch(label: string, fn: () => void): void {
    if (this.batchDepth === 0) {
      this.batchBefore = this.doc;
      this.batchEmits = [];
      this.batchLabel = label;
    }
    this.batchDepth++;
    try {
      fn();
    } finally {
      this.batchDepth--;
      if (this.batchDepth === 0) {
        const before = this.batchBefore as TyposDocument;
        this.batchBefore = null;
        if (this.doc !== before) {
          this.pushHistory(this.batchLabel, before);
          for (const e of this.batchEmits) this.emitter.emit(e.name, e.payload);
          this.afterChange(this.batchLabel);
        }
        this.batchEmits = [];
      }
    }
  }

  /* ---------------------------------------------------------------- */
  /* Historique                                                        */
  /* ---------------------------------------------------------------- */

  undo(): boolean {
    const entry = this.undoStack.pop();
    if (!entry) return false;
    this.redoStack.push({ label: entry.label, snapshot: this.doc, at: Date.now() });
    this.doc = entry.snapshot;
    this.pruneSelection();
    this.emitter.emit("history:undo", { label: entry.label });
    this.emitter.emit("document:changed", { document: this.doc, label: entry.label });
    this.setDirty(documentHash(this.doc) !== this.savedHash);
    return true;
  }

  redo(): boolean {
    const entry = this.redoStack.pop();
    if (!entry) return false;
    this.undoStack.push({ label: entry.label, snapshot: this.doc, at: Date.now() });
    this.doc = entry.snapshot;
    this.pruneSelection();
    this.emitter.emit("history:redo", { label: entry.label });
    this.emitter.emit("document:changed", { document: this.doc, label: entry.label });
    this.setDirty(documentHash(this.doc) !== this.savedHash);
    return true;
  }

  /* ---------------------------------------------------------------- */
  /* Interne                                                           */
  /* ---------------------------------------------------------------- */

  private template(
    templateId?: string,
    doc: TyposDocument = this.doc,
  ): TyposTemplate | null {
    const id = templateId ?? doc.activeTemplateId;
    return doc.templates.find((t) => t.id === id) ?? null;
  }

  private withTemplate(
    doc: TyposDocument,
    templateId: string,
    patch: Partial<TyposTemplate>,
  ): TyposDocument {
    return {
      ...doc,
      templates: doc.templates.map((t) =>
        t.id === templateId ? { ...t, ...patch } : t,
      ),
    };
  }

  /**
   * LE point de passage de toute mutation : produit le nouveau document,
   * recalcule les dérivées des templates touchés, gère l'historique
   * (avec coalescence), émet les événements, met à jour le dirty.
   * Retourne false si la mutation n'a rien changé.
   */
  private commit(
    label: string,
    produce: (doc: TyposDocument) => {
      doc: TyposDocument;
      emits: CommitEmit[];
      recompute?: string[];
    } | null,
    options: CommitOptions = {},
  ): boolean {
    const before = this.doc;
    const result = produce(before);
    if (!result || result.doc === before) return false;

    let next = result.doc;
    if (result.recompute?.length) {
      next = {
        ...next,
        templates: next.templates.map((t) =>
          result.recompute?.includes(t.id)
            ? {
                ...t,
                tree: recomputeDerivedDirectives(t.tree, {
                  documentId: next.id,
                  templateId: t.id,
                  target: t.target,
                  directivePrefix: next.settings.directivePrefix,
                }),
              }
            : t,
        ),
      };
    }
    next = { ...next, updatedAt: this.now() };
    this.doc = next;
    this.pruneSelection();

    if (this.batchDepth > 0) {
      this.batchEmits.push(...result.emits);
      return true;
    }

    this.pushHistory(label, before, options.coalesceKey);
    for (const e of result.emits) this.emitter.emit(e.name, e.payload);
    this.afterChange(label);
    return true;
  }

  private pushHistory(
    label: string,
    before: TyposDocument,
    coalesceKey?: string,
  ): void {
    const last = this.undoStack[this.undoStack.length - 1];
    const nowMs = Date.now();
    if (
      coalesceKey &&
      last?.coalesceKey === coalesceKey &&
      nowMs - last.at < this.coalesceWindowMs
    ) {
      // Fusion : on garde le snapshot le plus ancien, on rafraîchit l'horloge.
      last.at = nowMs;
    } else {
      this.undoStack.push({ label, snapshot: before, at: nowMs, coalesceKey });
      if (this.undoStack.length > this.historyLimit) this.undoStack.shift();
    }
    this.redoStack = [];
    this.emitter.emit("history:push", { label, depth: this.undoStack.length });
  }

  private afterChange(label: string): void {
    this.emitter.emit("document:changed", { document: this.doc, label });
    this.setDirty(true);
  }

  private setDirty(dirty: boolean): void {
    if (this.dirtyFlag !== dirty) {
      this.dirtyFlag = dirty;
      this.emitter.emit("dirty:changed", { dirty });
    }
  }

  private pruneSelection(): void {
    if (this.selectionIds.length === 0) return;
    const valid = this.selectionIds.filter((id) =>
      this.doc.templates.some((t) => findById(t.tree, id)),
    );
    if (valid.length !== this.selectionIds.length) {
      this.selectionIds = valid;
      this.emitter.emit("selection:changed", { ids: [...valid] });
    }
  }

  private resetTransient(): void {
    this.undoStack = [];
    this.redoStack = [];
    this.selectionIds = [];
    this.savedHash = documentHash(this.doc);
    this.setDirty(false);
  }
}
