import type {
  DirectiveValue,
  EmitProfile,
  HtmlGenOptions,
  TyposElement,
} from "./types.js";
import {
  DEFAULT_DIRECTIVE_PREFIX,
  DIRECTIVE_REGISTRY,
  directiveKey,
  emittedInProfile,
} from "./registry.js";
import { VOID_TAGS } from "./element.js";
import { walk } from "./tree.js";

/**
 * JSON → HTML. Déterministe : le même arbre + les mêmes options
 * produisent toujours exactement le même HTML.
 *
 * Règles (v1 conservées) :
 * - balises void fermées automatiquement, sans enfants ni innerHtml ;
 * - innerHtml émis tel quel SEULEMENT si pas d'enfants ;
 * - script émis en <script data-<prefix>-script-for="id"> juste après
 *   l'élément ;
 * - customCss l'emporte sur tout : agrégé dans un <style> émis en tête,
 *   scopé par [_-tag-id] (déclarations nues enveloppées ; règles
 *   complètes — contenant "{" — émises telles quelles, l'auteur scope).
 *
 * Ordre d'émission des attributs (déterminisme) :
 *   directives (ordre du registre) → attrs (ordre alphabétique)
 *   → class → style.
 */

const ESCAPE_RE = /[&<>"']/g;
const ESCAPE_MAP: Record<string, string> = {
  "&": "&amp;",
  "<": "&lt;",
  ">": "&gt;",
  '"': "&quot;",
  "'": "&#39;",
};

export function escapeAttr(value: string): string {
  return value.replace(ESCAPE_RE, (c) => ESCAPE_MAP[c] ?? c);
}

/** camelCase → kebab-case (backgroundColor → background-color). */
export function toKebab(prop: string): string {
  return prop.replace(/[A-Z]/g, (m) => `-${m.toLowerCase()}`);
}

function styleAttr(styleOptions: Record<string, string>): string {
  const entries = Object.entries(styleOptions)
    .filter(([, v]) => v !== "")
    .map(([k, v]) => [toKebab(k), v] as const)
    .sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0));
  if (entries.length === 0) return "";
  return entries.map(([k, v]) => `${k}: ${v}`).join("; ");
}

function directiveAttrs(
  el: TyposElement,
  profile: EmitProfile,
  prefix: string,
): string[] {
  if (profile === "none") return [];
  const out: string[] = [];
  for (const spec of DIRECTIVE_REGISTRY) {
    if (spec.scope === "script") continue;
    if (!emittedInProfile(spec, profile)) continue;
    const key = directiveKey(spec.short, prefix);
    const value: DirectiveValue | undefined = el.directives[key];
    if (value === undefined || value === null || value === "") continue;
    // Booléens : n'émettre que les vrais (locked, hidden…).
    if (typeof value === "boolean" && !value) continue;
    out.push(`${key}="${escapeAttr(String(value))}"`);
  }
  return out;
}

function openTag(
  el: TyposElement,
  profile: EmitProfile,
  prefix: string,
): string {
  const parts: string[] = [el.type];
  parts.push(...directiveAttrs(el, profile, prefix));
  for (const [key, value] of Object.entries(el.attrs).sort(([a], [b]) =>
    a < b ? -1 : a > b ? 1 : 0,
  )) {
    parts.push(value === "" ? key : `${key}="${escapeAttr(value)}"`);
  }
  if (el.classes.length > 0) {
    parts.push(`class="${escapeAttr(el.classes.join(" "))}"`);
  }
  const style = styleAttr(el.styleOptions);
  if (style) parts.push(`style="${escapeAttr(style)}"`);
  return `<${parts.join(" ")}`;
}

/**
 * Génère le HTML d'un élément (et de son sous-arbre).
 * N'inclut PAS le bloc <style> agrégé — voir treeToHtml() pour la
 * sortie complète d'un arbre.
 */
export function elementToHtml(
  el: TyposElement,
  options: HtmlGenOptions = {},
): string {
  const profile = options.profile ?? "runtime";
  const prefix = options.directivePrefix ?? DEFAULT_DIRECTIVE_PREFIX;
  const indent = options.indent ?? "  ";
  const includeScripts = options.includeScripts ?? true;
  const scriptForKey = directiveKey("script-for", prefix);

  const lines: string[] = [];
  const emit = (el2: TyposElement, depth: number): void => {
    const pad = indent ? indent.repeat(depth) : "";
    const open = openTag(el2, profile, prefix);

    if (VOID_TAGS.has(el2.type)) {
      lines.push(`${pad}${open} />`);
    } else if (el2.children.length > 0) {
      lines.push(`${pad}${open}>`);
      for (const child of el2.children) emit(child, depth + 1);
      lines.push(`${pad}</${el2.type}>`);
    } else if (el2.innerHtml) {
      // innerHtml brut, opaque, émis tel quel (une seule ligne logique).
      lines.push(`${pad}${open}>${el2.innerHtml}</${el2.type}>`);
    } else {
      lines.push(`${pad}${open}></${el2.type}>`);
    }

    if (includeScripts && el2.script) {
      lines.push(
        `${pad}<script ${scriptForKey}="${escapeAttr(el2.id)}">${el2.script}</script>`,
      );
    }
  };

  emit(el, 0);
  return indent ? lines.join("\n") : lines.join("");
}

/**
 * Agrège les customCss de l'arbre en un bloc CSS unique.
 * - Déclarations nues (pas de "{") : enveloppées dans
 *   [<prefix>-tag-id="…"] { … } — l'attribut-sélecteur, émis après le
 *   style inline dans la cascade du bloc, garantit l'override.
 * - Règles complètes (contiennent "{") : émises telles quelles.
 */
export function collectCustomCss(
  root: TyposElement,
  prefix: string = DEFAULT_DIRECTIVE_PREFIX,
): string {
  const idKey = directiveKey("id", prefix);
  const blocks: string[] = [];
  walk(root, (el) => {
    const css = el.customCss.trim();
    if (!css) return;
    if (css.includes("{")) {
      blocks.push(`/* ${el.id} */\n${css}`);
    } else {
      blocks.push(`[${idKey}="${el.id}"] {\n  ${css}\n}`);
    }
  });
  return blocks.join("\n\n");
}

/**
 * Sortie complète d'un arbre : <style> agrégé (si demandé) + HTML.
 */
export function treeToHtml(
  root: TyposElement,
  options: HtmlGenOptions = {},
): string {
  const prefix = options.directivePrefix ?? DEFAULT_DIRECTIVE_PREFIX;
  const includeStyle = options.includeStyle ?? true;
  const parts: string[] = [];
  if (includeStyle) {
    const css = collectCustomCss(root, prefix);
    if (css) {
      parts.push(`<style ${prefix}-tag-style-for="${escapeAttr(root.id)}">\n${css}\n</style>`);
    }
  }
  parts.push(elementToHtml(root, options));
  return parts.join("\n");
}
