import type { HtmlParseOptions, TyposElement } from "./types.js";
import {
  DEFAULT_DIRECTIVE_PREFIX,
  directiveKey,
  isTyposDirectiveKey,
  specForKey,
} from "./registry.js";
import { createElement } from "./element.js";

/**
 * HTML (+ CSS optionnel) → arbre Typos. Chemin inverse de elementToHtml.
 *
 * - Préserve les directives Typos déjà présentes (id compris) ; génère
 *   ce qui manque. Les clés "<prefix>-…" inconnues du registre sont
 *   conservées telles quelles (forward-compat).
 * - Les <script data-<prefix>-script-for="id"> sont extraits du flux et
 *   rattachés au champ `script` de leur élément cible.
 * - class → classes[], style → styleOptions, le reste des attributs → attrs.
 * - Le CSS fourni est rattaché au customCss de la racine.
 * - Si le HTML a plusieurs racines, elles sont enveloppées dans une div.
 *
 * S'appuie sur DOMParser (navigateur, ou happy-dom/jsdom en environnement
 * de test/Node). Erreur explicite si indisponible.
 */
export function parseHtmlToTree(options: HtmlParseOptions): TyposElement {
  const prefix = options.directivePrefix ?? DEFAULT_DIRECTIVE_PREFIX;
  const ParserCtor = (globalThis as { DOMParser?: typeof DOMParser }).DOMParser;
  if (!ParserCtor) {
    throw new Error(
      "Typos: DOMParser indisponible — parseHtmlToTree requiert un environnement DOM (navigateur, happy-dom ou jsdom).",
    );
  }

  const doc = new ParserCtor().parseFromString(options.html, "text/html");
  const scriptForKey = directiveKey("script-for", prefix);
  const idKeyGlobal = directiveKey("id", prefix);
  // Le document porte-t-il des estampilles Typos quelque part ?
  // Si oui : seuls les éléments estampillés sont structurels, le reste
  // est du contenu riche opaque (innerHtml). Si non (HTML étranger) :
  // tout est converti en structure.
  const docHasStamps =
    doc.body.querySelector(`[${cssEscape(idKeyGlobal)}]`) !== null;

  // 1) Extraire les scripts scopés et indexer par id cible.
  const scriptsById = new Map<string, string>();
  for (const script of Array.from(doc.querySelectorAll(`script[${cssEscape(scriptForKey)}]`))) {
    const target = script.getAttribute(scriptForKey);
    if (target) {
      scriptsById.set(
        target,
        `${scriptsById.get(target) ?? ""}${script.textContent ?? ""}`,
      );
    }
    script.remove();
  }
  // Les <style *-tag-style-for> issus de treeToHtml sont retirés du flux
  // (le customCss vit dans le JSON, pas dans le HTML re-parsé).
  for (const style of Array.from(
    doc.querySelectorAll(`style[${cssEscape(`${prefix}-tag-style-for`)}]`),
  )) {
    style.remove();
  }

  // 2) Convertir récursivement.
  const convert = (node: Element): TyposElement => {
    const idKey = directiveKey("id", prefix);
    const nameKey = directiveKey("name", prefix);
    const existingId = node.getAttribute(idKey) ?? undefined;

    const attrs: Record<string, string> = {};
    const directives: Record<string, string | number | boolean> = {};
    let classes: string[] = [];
    const styleOptions: Record<string, string> = {};

    for (const attr of Array.from(node.attributes)) {
      const { name, value } = attr;
      if (name === "class") {
        classes = value.split(/\s+/).filter(Boolean);
      } else if (name === "style") {
        for (const decl of value.split(";")) {
          const colon = decl.indexOf(":");
          if (colon > 0) {
            const prop = decl.slice(0, colon).trim();
            const val = decl.slice(colon + 1).trim();
            if (prop && val) styleOptions[prop] = val;
          }
        }
      } else if (isTyposDirectiveKey(name, prefix)) {
        const spec = specForKey(name, prefix);
        // Recoder les types simples (les dérivées numériques/booléennes
        // reviennent en texte du HTML ; elles seront recalculées de toute
        // façon — on ne conserve fidèlement que les déclarées).
        if (spec?.mode === "derived") continue;
        if (value === "true" || value === "false") {
          directives[name] = value === "true";
        } else if (value !== "" && !Number.isNaN(Number(value)) && spec?.short === "revision") {
          directives[name] = Number(value);
        } else {
          directives[name] = value;
        }
      } else {
        attrs[name] = value;
      }
    }

    const componentIdKey = directiveKey("component-id", prefix);
    const componentTypeKey = directiveKey("component-type", prefix);
    const componentNameKey = directiveKey("component-name", prefix);
    const isComponentRoot =
      componentTypeKey in directives || componentNameKey in directives;

    const allChildElements = Array.from(node.children);
    const structural =
      allChildElements.length > 0 &&
      (!docHasStamps ||
        allChildElements.some((c) => c.hasAttribute(idKeyGlobal)));
    const childElements = structural ? allChildElements : [];
    const hasElementChildren = childElements.length > 0;

    const el = createElement(node.tagName.toLowerCase(), {
      id: existingId,
      name:
        typeof directives[nameKey] === "string"
          ? (directives[nameKey] as string)
          : undefined,
      origin: "import",
      isComponentRoot,
      componentRef: isComponentRoot
        ? {
            type: String(directives[componentTypeKey] ?? ""),
            name: String(directives[componentNameKey] ?? ""),
            componentId: String(directives[componentIdKey] ?? ""),
          }
        : null,
      attrs,
      classes,
      styleOptions,
      innerHtml: hasElementChildren ? "" : (node.innerHTML ?? "").trim(),
      children: childElements.map(convert),
      directivePrefix: prefix,
    });

    return {
      ...el,
      // Les déclarées importées écrasent les valeurs par défaut de la
      // factory ; l'id reste cohérent avec el.id.
      directives: {
        ...el.directives,
        ...directives,
        [idKey]: el.id,
      },
      script: scriptsById.get(el.id) ?? "",
    };
  };

  const roots = Array.from(doc.body.children);
  let tree: TyposElement;
  if (roots.length === 1 && roots[0]) {
    tree = convert(roots[0]);
  } else if (roots.length === 0) {
    tree = createElement("div", { name: "root", origin: "import" });
  } else {
    tree = createElement("div", {
      name: "root",
      origin: "import",
      children: roots.map(convert),
    });
  }

  if (options.css?.trim()) {
    tree = {
      ...tree,
      customCss: tree.customCss
        ? `${tree.customCss}\n${options.css.trim()}`
        : options.css.trim(),
    };
  }

  return tree;
}

/** Échappe un nom d'attribut pour un sélecteur querySelectorAll. */
function cssEscape(name: string): string {
  return name.replace(/[^a-zA-Z0-9_-]/g, (c) => `\\${c}`);
}
