import type { EmitProfile } from "../core/types.js";
import type { TyposEngine } from "../engine/TyposEngine.js";
import { h, makeDisposer, replaceChildren, debounce } from "./dom.js";

/* ------------------------------------------------------------------ */
/* Tokeniseur léger (zéro dépendance, HTML + JSON)                     */
/* ------------------------------------------------------------------ */

type TokenKind = "tag" | "attr-name" | "attr-value" | "text" | "comment"
  | "punct" | "key" | "string" | "number" | "boolean" | "null";

interface Token { kind: TokenKind; text: string }

function tokenizeHtml(line: string): Token[] {
  const tokens: Token[] = [];
  const re = /(<!--[\s\S]*?-->)|(<\/?[a-zA-Z][a-zA-Z0-9-]*)|(\s+[a-zA-Z][a-zA-Z0-9_:.-]*)(="[^"]*")?|(>|\/?>)|([^<>]+)/g;
  let m: RegExpExecArray | null;
  while ((m = re.exec(line))) {
    if (m[1]) { tokens.push({ kind: "comment", text: m[1] }); }
    else if (m[2]) { tokens.push({ kind: "tag", text: m[2] }); }
    else if (m[3]) {
      tokens.push({ kind: "attr-name", text: m[3] });
      if (m[4]) tokens.push({ kind: "attr-value", text: m[4] });
    }
    else if (m[5]) { tokens.push({ kind: "punct", text: m[5] }); }
    else if (m[6]) { tokens.push({ kind: "text", text: m[6] }); }
  }
  if (!tokens.length && line) tokens.push({ kind: "text", text: line });
  return tokens;
}

function tokenizeJson(line: string): Token[] {
  const tokens: Token[] = [];
  const re = /("(?:[^"\\]|\\.)*")\s*(:)|("(?:[^"\\]|\\.)*")|(true|false)|(null)|(-?\d+(?:\.\d+)?(?:[eE][+-]?\d+)?)|([{}\[\],:])|(\s+)|([^\s"{}[\],:]+)/g;
  let m: RegExpExecArray | null;
  while ((m = re.exec(line))) {
    if (m[1]) { tokens.push({ kind: "key", text: m[1] }); tokens.push({ kind: "punct", text: m[2]! }); }
    else if (m[3]) { tokens.push({ kind: "string", text: m[3] }); }
    else if (m[4]) { tokens.push({ kind: "boolean", text: m[4] }); }
    else if (m[5]) { tokens.push({ kind: "null", text: m[5] }); }
    else if (m[6]) { tokens.push({ kind: "number", text: m[6] }); }
    else if (m[7]) { tokens.push({ kind: "punct", text: m[7] }); }
    else if (m[8]) { tokens.push({ kind: "text", text: m[8] }); }
    else if (m[9]) { tokens.push({ kind: "text", text: m[9] }); }
  }
  if (!tokens.length && line) tokens.push({ kind: "text", text: line });
  return tokens;
}

/* ------------------------------------------------------------------ */
/* Détection des blocs pliables                                        */
/* ------------------------------------------------------------------ */

interface FoldRange { start: number; end: number; collapsed: boolean }

/** Détecte les blocs pliables par indentation + balises/accolades. */
function detectFolds(lines: string[], mode: "html" | "json"): FoldRange[] {
  const ranges: FoldRange[] = [];
  const stack: number[] = [];
  for (let i = 0; i < lines.length; i++) {
    const trimmed = lines[i]!.trim();
    if (mode === "json") {
      if (trimmed.endsWith("{") || trimmed.endsWith("[") || trimmed.endsWith("{,") || trimmed.endsWith("[,")) {
        stack.push(i);
      } else if (trimmed === "}" || trimmed === "}," || trimmed === "]" || trimmed === "],") {
        const start = stack.pop();
        if (start !== undefined && i - start > 1) {
          ranges.push({ start, end: i, collapsed: false });
        }
      }
    } else {
      // HTML : ouverture + fermeture par balise.
      const openMatch = trimmed.match(/^<([a-zA-Z][a-zA-Z0-9-]*)[\s>]/);
      const closeMatch = trimmed.match(/^<\/([a-zA-Z][a-zA-Z0-9-]*)\s*>/);
      const selfClose = trimmed.endsWith("/>") || trimmed.match(/^<(img|input|br|hr|meta|link|col)\b/i);
      if (openMatch && !selfClose) {
        stack.push(i);
      } else if (closeMatch) {
        // Cherche la dernière ouverture du même tag.
        for (let j = stack.length - 1; j >= 0; j--) {
          const openLine = lines[stack[j]!]!.trim();
          const m2 = openLine.match(/^<([a-zA-Z][a-zA-Z0-9-]*)[\s>]/);
          if (m2 && m2[1]!.toLowerCase() === closeMatch[1]!.toLowerCase()) {
            const start = stack.splice(j, 1)[0]!;
            if (i - start > 1) ranges.push({ start, end: i, collapsed: false });
            break;
          }
        }
      }
    }
  }
  return ranges.sort((a, b) => a.start - b.start);
}

/* ------------------------------------------------------------------ */
/* Vue code façon éditeur                                              */
/* ------------------------------------------------------------------ */

/**
 * Rendu code avec :
 *  · numéros de ligne dans une gouttière fixe ;
 *  · coloration syntaxique (HTML et JSON) ;
 *  · fold/unfold (▶/▼) sur les blocs pliables ;
 *  · surlignage de la sélection + scroll auto.
 */
export class TyposHtmlView {
  private disposer = makeDisposer();
  private mode: "html" | "json" = "html";
  private profile: EmitProfile;
  private visible = false;
  private codeWrap: HTMLElement;
  private gutterEl: HTMLElement;
  private linesEl: HTMLElement;
  private folds: FoldRange[] = [];
  private rawLines: string[] = [];
  private refresh = debounce(() => this.renderCode(), 60);

  constructor(
    private container: HTMLElement,
    private engine: TyposEngine,
  ) {
    this.profile = engine.document.settings.emitProfile;
    this.gutterEl = h("div", { class: "typos-gutter" });
    this.linesEl = h("div", { class: "typos-lines" });
    this.codeWrap = h("div", { class: "typos-code" }, this.gutterEl, this.linesEl);
    this.renderShell();

    const onChange = (): void => { if (this.visible) this.refresh(); };
    this.disposer.add(engine.on("document:changed", onChange));
    this.disposer.add(engine.on("document:loaded", onChange));
    this.disposer.add(engine.on("document:new", onChange));
    this.disposer.add(engine.on("template:activated", onChange));
    this.disposer.add(
      engine.on("selection:changed", () => { if (this.visible) this.highlightSelection(); }),
    );
  }

  setVisible(visible: boolean): void {
    this.visible = visible;
    if (visible) this.renderCode();
  }

  private renderShell(): void {
    const profileSelect = h("select", {
      class: "typos-select",
      on: { change: (e) => { this.profile = (e.target as HTMLSelectElement).value as EmitProfile; this.renderCode(); } },
    });
    for (const p of ["none", "minimal", "runtime", "full"] as const) {
      const opt = h("option", { attrs: { value: p }, text: p });
      if (p === this.profile) opt.selected = true;
      profileSelect.append(opt);
    }

    const modeBtn = (mode: "html" | "json", label: string): HTMLButtonElement =>
      h("button", {
        class: `typos-chip ${this.mode === mode ? "is-active" : ""}`,
        text: label,
        on: { click: () => { this.mode = mode; this.renderShell(); this.renderCode(); } },
      });

    const expandAll = h("button", {
      class: "typos-btn", text: "⊞ Tout",
      title: "Déplier tout",
      on: { click: () => { this.folds.forEach(f => f.collapsed = false); this.paintLines(); } },
    });
    const collapseAll = h("button", {
      class: "typos-btn", text: "⊟ Tout",
      title: "Plier tout",
      on: { click: () => { this.folds.forEach(f => f.collapsed = true); this.paintLines(); } },
    });

    replaceChildren(
      this.container,
      h("div", { class: "typos-codebar" },
        modeBtn("html", "HTML"),
        modeBtn("json", "JSON"),
        h("span", { class: "typos-spacer" }),
        expandAll, collapseAll,
        this.mode === "html" ? h("span", { class: "typos-field-label", text: "profil" }) : null,
        this.mode === "html" ? profileSelect : null,
        h("button", {
          class: "typos-btn", text: "Copier",
          on: { click: () => { void navigator.clipboard?.writeText(this.rawLines.join("\n")).catch(() => {}); } },
        }),
      ),
      this.codeWrap,
    );
    this.renderCode();
  }

  /* ────────────────────────── rendu du code ─────────────────────── */

  private renderCode(): void {
    const source = this.mode === "html"
      ? this.engine.getHtml({ profile: this.profile })
      : this.engine.toJSON();
    this.rawLines = source.split("\n");
    this.folds = detectFolds(this.rawLines, this.mode);
    this.paintLines();
  }

  /** Peint gouttière + lignes, en respectant les folds. */
  private paintLines(): void {
    this.gutterEl.textContent = "";
    this.linesEl.textContent = "";

    const hidden = new Set<number>();
    for (const f of this.folds) {
      if (f.collapsed) {
        for (let i = f.start + 1; i <= f.end; i++) hidden.add(i);
      }
    }

    const tokenize = this.mode === "html" ? tokenizeHtml : tokenizeJson;
    const selectedId = this.engine.selection[0];

    for (let i = 0; i < this.rawLines.length; i++) {
      if (hidden.has(i)) continue;
      const raw = this.rawLines[i]!;
      const lineNum = i + 1;

      // Gouttière : numéro de ligne + toggle fold.
      const fold = this.folds.find(f => f.start === i);
      const gutterRow = h("div", { class: "typos-gutter-row" });
      if (fold) {
        const toggle = h("span", {
          class: `typos-fold-toggle ${fold.collapsed ? "is-collapsed" : ""}`,
          text: fold.collapsed ? "▶" : "▼",
          title: fold.collapsed ? "Déplier" : "Plier",
          on: { click: () => { fold.collapsed = !fold.collapsed; this.paintLines(); } },
        });
        gutterRow.append(toggle);
      }
      gutterRow.append(h("span", { class: "typos-line-num", text: String(lineNum) }));
      this.gutterEl.append(gutterRow);

      // Ligne tokenisée.
      const isSelected = !!(selectedId && raw.includes(selectedId));
      const lineEl = h("div", {
        class: `typos-code-line ${isSelected ? "is-selected" : ""}`,
        attrs: { "data-line": String(lineNum) },
      });

      if (fold?.collapsed) {
        // Ligne effondrée : affiche le début + résumé.
        const tokens = tokenize(raw);
        for (const tok of tokens) lineEl.append(this.spanFor(tok));
        const hiddenCount = fold.end - fold.start - 1;
        lineEl.append(h("span", {
          class: "typos-fold-badge",
          text: ` ··· ${hiddenCount} ligne${hiddenCount > 1 ? "s" : ""}`,
          title: "Clic pour déplier",
          on: { click: () => { fold.collapsed = false; this.paintLines(); } },
        }));
      } else {
        const tokens = tokenize(raw);
        for (const tok of tokens) lineEl.append(this.spanFor(tok));
        if (!tokens.length) lineEl.textContent = "\u00a0";
      }

      this.linesEl.append(lineEl);
    }

    this.highlightSelection();
  }

  private spanFor(tok: Token): HTMLSpanElement {
    return h("span", { class: `typos-tok-${tok.kind}`, text: tok.text });
  }

  private highlightSelection(): void {
    const id = this.engine.selection[0];
    let found: HTMLElement | null = null;
    for (const row of Array.from(this.linesEl.children) as HTMLElement[]) {
      const hit = !!(id && row.textContent?.includes(id));
      row.classList.toggle("is-selected", hit);
      if (hit && !found) found = row;
    }
    if (found) {
      const p = this.codeWrap.getBoundingClientRect();
      const r = found.getBoundingClientRect();
      if (r.top < p.top || r.bottom > p.bottom) {
        this.codeWrap.scrollTop += r.top - p.top - this.codeWrap.clientHeight / 3;
      }
    }
  }

  destroy(): void {
    this.disposer.flush();
    this.container.textContent = "";
  }
}
